}

Method.Source:
/// <summary>
/// Run snapshot once
/// </summary>
/// <param name = "_externalTrackingId">Trial balance snapshot external tracking Id</param>
/// <returns><c>METPaymentStatusUpdateResponse</c></returns>
public METPaymentStatusUpdateResponse runOnce(Guid _externalTrackingId)
{
    METProcessingStatus     result;
    ErrorMessage            message;

    [result, message] = this.run(_externalTrackingId);

    return METPaymentStatusUpdateResponse::newFromParameters(result, message);
}

/// <summary>
/// Run method
/// </summary>
/// <param name = "_externalTrackingId">Trial balance snapshot external tracking Id</param>
/// <returns>Container with result and message</returns>
private container run(Guid _externalTrackingId)
{
    #OCCRetryCount
    METProcessingStatus                         processingStatus;
    ErrorMessage                                processingMessage;

    try
    {
        ttsbegin;
        LedgerTrialBalanceSnapshotHeader header = LedgerTrialBalanceSnapshotHeader::METFindTrackingId(_externalTrackingId);

        if (header)
        {
            if (header.Status != LedgerTrialBalanceSnapshotStatus::InProcess)
            {
                // copied from Form LedgerTrialBalanceSnapshots - RunOnce button clicked()
                if (header.ProcessScheduleSeries == 0)
                {
                    Args arg = new Args();
                    arg.record(header);

                    // extensibility request 1019409 
                    //LedgerTrialBalanceFiscalYearSnapshotController::main(arg);

                    //Temporary method to call the Trial balance snapshot logic until the extensibility request 1019409 is applied
                    this.execute(arg);

                    processingStatus = METProcessingStatus::Success;
                }
                else
                {
                    // created from process automation, cannot manually run snapshot
                    processingMessage = "@MET:TrialBalanceSnapshotServiceProcessScheduleSeriesError";
                }

            }
            else
            {
                // Already in process
                processingMessage = "@MET:TrialBalanceSnapshotServiceInProcessError";
            }
        }
        else
        {
            // trial balance snapshot not found                
            processingMessage = strFmt("@MET:TrialBalanceSnapshotServiceNotFoundError", _externalTrackingId);
        }

        ttscommit;
    }
    catch (Exception::Error)
    {
        SysInfologEnumerator        enumerator;
        SysInfologMessageStruct     msgStruct;
        Exception                   exceptionLocal;
        boolean first = true;

        // Get error message from infolog
        enumerator = SysInfologEnumerator::newData(infolog.cut());

        while (enumerator.moveNext())
        {
            msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
            exceptionLocal = enumerator.currentException();

            if (exceptionLocal == Exception::Error)
            {
                if (first)
                {
                    processingMessage = msgStruct.message();
                    first = false;
                }
                else
                {
                    processingMessage = strfmt('%1 %2', processingMessage, msgStruct.message());
                }                   
            }
        }
    }
    catch (Exception::CLRError)
    {
        System.Exception interopException = CLRInterop::getLastException();
        processingMessage = interopException.ToString();
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                processingMessage = "@WAX:UpdateConflictExceptionMessage";
            }
            else
            {
                retry;
            }
        }
        else
        {
            processingMessage = "@WAX:UpdateConflictExceptionMessage";
        }
    }
    catch
    {
        processingMessage = "@WAX:UpdateCancelled";
    }

    if (processingMessage)
    {
        processingStatus = METProcessingStatus::Error;
    }

    return [processingStatus, processingMessage];
}

/// <summary>
/// This method will call the main methid of <c>LedgerTrialBalanceFiscalYearSnapshotController</c> class using reflection. 
/// This is a temporary fix until the extensibility requet is applied
/// </summary>
/// <param name = "_args">Argument with <t>LedgerTrialBalanceSnapshotHeader</t> record buffer</param>
private void execute(Args _args)
{
    str className = identifierStr('LedgerTrialBalanceFiscalYearSnapshotController'); //Class name as a string
    str methodName = identifierStr('main'); //Static method name

    SysDictClass dictClass = new SysDictClass(className2Id(className));

    if (dictClass.hasStaticMethod(methodName))
    {
        dictClass.callStatic(methodName, _args);
    }
}
